import { notFound } from 'next/navigation';
import { prisma } from '@/lib/prisma';
import { normalizeBundleSlug, publicBundlePayload } from '@/lib/bundles';
import BundleOrderForm from '@/components/BundleOrderForm';
import styles from '@/components/BundleOffer.module.css';
export const dynamic='force-dynamic';
export async function generateMetadata({params}){const{slug}=await params;const b=await prisma.bundleOffer.findUnique({where:{slug:normalizeBundleSlug(slug)},select:{title:true,description:true,imageUrl:true}});if(!b)return{title:'Bundle Offer'};return{title:`${b.title} | Arone Bd`,description:b.description||'Special combo offer from Arone Bd',openGraph:{title:b.title,description:b.description||'',images:b.imageUrl?[b.imageUrl]:[]}}}
export default async function Page({params}){const{slug}=await params;const row=await prisma.bundleOffer.findUnique({where:{slug:normalizeBundleSlug(slug)}});if(!row)notFound();const bundle=await publicBundlePayload(prisma,row,1);return <main style={{background:'#f7faf5',padding:'42px 0 70px'}}><div className={styles.wrap}><div className={styles.hero}><section className={styles.card}><span className={styles.badge}>{bundle.badge||'COMBO OFFER'}</span><h1 className={styles.title}>{bundle.title}</h1>{bundle.description&&<p className={styles.description}>{bundle.description}</p>}{bundle.imageUrl&&<img className={styles.cover} src={bundle.imageUrl} alt={bundle.title}/>}<div className={styles.items}>{bundle.items.map(item=><div className={styles.item} key={item.productId}>{item.product.imageUrl?<img src={item.product.imageUrl} alt=""/>:<span/>}<div><b>{item.product.name}</b><small>{item.quantity} × ৳{Number(item.product.price).toLocaleString('en-US')}</small></div><strong>৳{Number(item.product.price*item.quantity).toLocaleString('en-US')}</strong></div>)}</div><div className={styles.priceBox}><del>৳{Number(bundle.pricing.regularSingle).toLocaleString('en-US')}</del><strong>৳{Number(bundle.pricing.offerSingle).toLocaleString('en-US')}</strong><span className={styles.save}>Save ৳{Number(bundle.pricing.bundleDiscountAmount).toLocaleString('en-US')}</span></div>{!bundle.available&&<div className={styles.error}>{bundle.unavailableReason}</div>}</section><BundleOrderForm bundle={bundle}/></div></div></main>}
